import sys
import json
import os

def format_date(value):
    """Convert a date string from YYYYMMDD to YYYY-MM-DD.
    If the value is empty or not a valid YYYYMMDD string, return None.
    """
    if not value:
        return None
    s = value.strip()
    # Already in YYYY-MM-DD format
    if len(s) == 10 and s[4] == '-' and s[7] == '-':
        return s
    # YYYYMMDD format
    if len(s) == 8 and s.isdigit():
        return f"{s[0:4]}-{s[4:6]}-{s[6:8]}"
    # Fallback: return the original string (should not happen for these fields)
    return s

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    # Mapping from (rule_id, fact_name) to (document_name, field_name)
    rule_defs = {
        ("fda.classified_30d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
        ("fda.classified_30d", "classification date"): ("fda_enforcement_reports", "center_classification_date"),
        ("fda.terminated_180d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
        ("fda.terminated_180d", "termination date"): ("fda_enforcement_reports", "termination_date"),
    }

    # Load the required document(s)
    doc_data = {}
    for doc_name in set(doc for doc, _ in rule_defs.values()):
        file_path = os.path.join(packet_dir, doc_name + ".json")
        if os.path.exists(file_path):
            with open(file_path, 'r') as f:
                doc_data[doc_name] = json.load(f)
        else:
            doc_data[doc_name] = {"results": []}

    def get_records(doc_name, entity):
        """Return all records in the document that match the entity (recall_number)."""
        data = doc_data.get(doc_name, {})
        records = []
        if isinstance(data, dict) and "results" in data:
            for rec in data["results"]:
                if rec.get("recall_number") == entity:
                    records.append(rec)
        return records

    output = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        result_obj = {}
        for fact_name in fact_names:
            key = (rule_id, fact_name)
            if key not in rule_defs:
                result_obj[fact_name] = "ABSENT"
                continue
            doc_name, field_name = rule_defs[key]
            records = get_records(doc_name, entity)
            # Collect non-empty values for the field
            values = []
            for rec in records:
                val = rec.get(field_name)
                if val is not None and val != "":
                    parsed = format_date(val)
                    if parsed is not None:
                        values.append(parsed)
            if not values:
                result_obj[fact_name] = "ABSENT"
            else:
                unique_vals = set(values)
                if len(unique_vals) == 1:
                    result_obj[fact_name] = [values[0], doc_name]
                else:
                    result_obj[fact_name] = "CONFLICT"
        output[pair] = result_obj

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

