import json
import os
import sys

# Mapping from rule_id to fact_name -> (document, field)
RULE_FACT_MAP = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    },
}

# Mapping from document to the field that identifies the entity
DOCUMENT_ENTITY_FIELD = {
    "fda_enforcement_reports": "recall_number",
}

def normalize_date(value):
    """Convert YYYYMMDD or YYYY-MM-DD to YYYY-MM-DD; return None if empty."""
    if value is None:
        return None
    s = str(value).strip()
    if not s:
        return None
    # YYYYMMDD
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:]}"
    # YYYY-MM-DD
    if len(s) == 10 and s[4] == '-' and s[7] == '-':
        return s
    # Fallback: return as is
    return s

def load_document(packet_dir, doc_name):
    """Load a JSON document from the packet directory. Returns a list of records."""
    path = os.path.join(packet_dir, doc_name + ".json")
    if not os.path.exists(path):
        return None
    with open(path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    if isinstance(data, dict):
        if "results" in data:
            r = data["results"]
            if isinstance(r, list):
                return r
            else:
                return [r]
        else:
            return [data]
    elif isinstance(data, list):
        return data
    else:
        return []

def get_values_for_field(records, entity_field, entity, field, is_date):
    """Collect non-empty values for the given field from records matching the entity."""
    values = []
    for rec in records:
        if rec.get(entity_field) == entity:
            val = rec.get(field)
            if val is not None:
                s = str(val).strip()
                if s != "":
                    if is_date:
                        s = normalize_date(s)
                    if s is not None and s != "":
                        values.append(s)
    return values

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    doc_cache = {}
    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])

        result = {}
        for fact_name in fact_names:
            if rule_id in RULE_FACT_MAP and fact_name in RULE_FACT_MAP[rule_id]:
                doc_name, field = RULE_FACT_MAP[rule_id][fact_name]
            else:
                result[fact_name] = "ABSENT"
                continue

            if doc_name not in doc_cache:
                doc_cache[doc_name] = load_document(packet_dir, doc_name)
            records = doc_cache[doc_name]

            if records is None:
                result[fact_name] = "ABSENT"
                continue

            entity_field = DOCUMENT_ENTITY_FIELD.get(doc_name)
            if entity_field is None:
                result[fact_name] = "ABSENT"
                continue

            is_date = "date" in fact_name.lower() or "date" in field.lower()
            values = get_values_for_field(records, entity_field, entity, field, is_date)

            if len(values) == 0:
                result[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                result[fact_name] = [values[0], doc_name]
            else:
                result[fact_name] = "CONFLICT"

        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

