import json
import os
import sys

def parse_date(s):
    """Convert a date string to YYYY-MM-DD, or None if not a valid date."""
    s = s.strip()
    if not s:
        return None
    # YYYYMMDD
    if len(s) == 8 and s.isdigit():
        return f"{s[0:4]}-{s[4:6]}-{s[6:8]}"
    # YYYY-MM-DD
    if len(s) == 10 and s[4] == '-' and s[7] == '-':
        return s
    return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load the FDA enforcement reports
    reports_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(reports_file, "r", encoding="utf-8") as f:
        reports_data = json.load(f)

    records = reports_data.get("results", [])
    doc_name = os.path.splitext(os.path.basename(reports_file))[0]

    # Index records by recall_number
    by_recall = {}
    for rec in records:
        rn = rec.get("recall_number")
        if rn:
            by_recall.setdefault(rn, []).append(rec)

    # Map fact names to the JSON field that establishes them
    fact_to_field = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date",
    }

    result = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::", 1)
        facts = manifest.get("facts", {}).get(rule_id, [])
        pair_result = {}
        for fact_name in facts:
            field = fact_to_field.get(fact_name)
            if not field:
                pair_result[fact_name] = "ABSENT"
                continue

            recs = by_recall.get(entity, [])
            values = []
            for rec in recs:
                raw = rec.get(field, "")
                val = parse_date(raw)
                if val is not None:
                    values.append(val)

            if not values:
                pair_result[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                pair_result[fact_name] = [values[0], doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        result[pair] = pair_result

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

