import json
import os
import sys

# Mapping from (rule_id, fact_name) to (document, field)
RULES = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    },
}

# Entity matching field for each document
ENTITY_FIELD = {
    "fda_enforcement_reports": "recall_number",
}

def format_date(value):
    """Convert YYYYMMDD to YYYY-MM-DD if applicable."""
    if len(value) == 8 and value.isdigit():
        return f"{value[:4]}-{value[4:6]}-{value[6:8]}"
    return value

def load_document(packet_dir, doc_name):
    """Load a JSON document from the packet directory."""
    file_path = os.path.join(packet_dir, doc_name + ".json")
    with open(file_path, "r") as f:
        data = json.load(f)
    return data

def find_records(data, entity_field, entity):
    """Find all records matching the entity."""
    records = []
    if isinstance(data, dict) and "results" in data:
        for record in data["results"]:
            if isinstance(record, dict) and record.get(entity_field) == entity:
                records.append(record)
    elif isinstance(data, list):
        for record in data:
            if isinstance(record, dict) and record.get(entity_field) == entity:
                records.append(record)
    return records

def extract_value(records, field):
    """Extract non-empty values for a field from matching records."""
    values = []
    for record in records:
        if field in record:
            val = record[field]
            if val is not None and val != "":
                values.append(val)
    return values

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r") as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]

    # Cache loaded documents
    doc_cache = {}

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts = facts_by_rule[rule_id]

        result[pair] = {}

        for fact in facts:
            if rule_id not in RULES or fact not in RULES[rule_id]:
                result[pair][fact] = "ABSENT"
                continue

            doc_name, field = RULES[rule_id][fact]

            # Load document if not cached
            if doc_name not in doc_cache:
                doc_cache[doc_name] = load_document(packet_dir, doc_name)

            data = doc_cache[doc_name]
            entity_field = ENTITY_FIELD[doc_name]
            records = find_records(data, entity_field, entity)

            if not records:
                result[pair][fact] = "ABSENT"
                continue

            values = extract_value(records, field)

            if not values:
                result[pair][fact] = "ABSENT"
                continue

            # Format dates
            formatted_values = [format_date(v) for v in values]

            unique_values = set(formatted_values)

            if len(unique_values) > 1:
                result[pair][fact] = "CONFLICT"
            else:
                result[pair][fact] = [formatted_values[0], doc_name]

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

