import sys
import os
import json
from collections import defaultdict

def format_date(s):
    """Convert YYYYMMDD to YYYY-MM-DD. Leave other formats unchanged."""
    if not s:
        return s
    s = s.strip()
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}"
    return s

def load_document(packet_dir, doc_name):
    """Load a JSON document from the packet directory by its base name."""
    path = os.path.join(packet_dir, doc_name + ".json")
    if not os.path.exists(path):
        return None
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

# Mapping from rule_id to fact name to (document, field)
RULE_FACT_MAP = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    }
}

# The field in the records that matches the entity in the manifest pairs
ENTITY_FIELD = "recall_number"

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    # Load the FDA enforcement reports document and index by recall_number
    doc_name = "fda_enforcement_reports"
    doc = load_document(packet_dir, doc_name)
    records = []
    if doc and isinstance(doc, dict) and "results" in doc:
        records = doc["results"]

    index = defaultdict(list)
    for rec in records:
        if isinstance(rec, dict):
            entity_val = rec.get(ENTITY_FIELD)
            if entity_val is not None:
                index[entity_val].append(rec)

    output = {}
    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        rule_id = rule_id.strip()
        entity = entity.strip()
        fact_names = facts_by_rule.get(rule_id, [])
        result = {}
        for fact_name in fact_names:
            mapping = RULE_FACT_MAP.get(rule_id, {}).get(fact_name)
            if mapping is None:
                result[fact_name] = "ABSENT"
                continue
            doc_name, field = mapping
            recs = index.get(entity, [])
            if not recs:
                result[fact_name] = "ABSENT"
                continue

            # Collect raw values from all matching records
            raw_values = []
            for rec in recs:
                val = rec.get(field, "")
                if val is None:
                    val = ""
                if isinstance(val, str):
                    val = val.strip()
                else:
                    val = str(val)
                raw_values.append(val)

            # Determine result based on agreement
            if all(v == "" for v in raw_values):
                result[fact_name] = "ABSENT"
            elif len(set(raw_values)) == 1:
                val = raw_values[0]
                if "date" in fact_name.lower():
                    val = format_date(val)
                result[fact_name] = [val, doc_name]
            else:
                result[fact_name] = "CONFLICT"
        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

